  ∀ ε : ℝ, 0 < ε → ∀ᶠ y : ℝ in atTop,
    |(Nat.primeCounting ⌊y⌋₊ : ℝ)-y/Real.log y| ≤ ε*(y/Real.log y)

OAI.NumberTheory.TotientAsymptotic.Prefi.text:
def prefixRegion (N : ℕ) (B C₀ : ℝ) (C : Fin N → ℝ) : Set (Fin N → ℝ) :=
  {u | (∀ i, C i ≤ prefixLinear N u i) ∧
    (∑ i : Fin N, a (i.val+1) * u i) ≤ B-C₀}

OAI.NumberTheory.TotientAsymptotic.Prime.text:
def FordUnitPrimeBoxInput : Prop :=
  ∃ C : ℝ, 0 < C ∧ ∀ m : ℕ, 1 ≤ m →
    |unitPrimeWeight m-1| ≤ C*Real.exp (-(m : ℝ))

OAI.Probability.TraceReconstruction.Init.text:
def sourceHalfMoment (B D : ℕ) (n : ℝ) (i : ℕ) : ℕ :=
  ⌈(10^8:ℝ)*2^(10*B)*(totalScoreExponent B D+B+1)*Real.log n/
    Real.log (sourceTargetScale B D n i)⌉₊

