def staircaseIndex (n : ℕ) : ℕ :=
  Nat.findGreatest (fun M => (Saxl.staircase M).card ≤ n ∧
    (Saxl.staircase M).card % 2 = n % 2) n

OAI.Computability.VertexCover.Basic:10.text:
