  GraphMachine.explicitGraph (repeated (Parameters.σ m) (Parameters.σ_between m hm).1 input)
    (Parameters.d m) (Parameters.t m)

OAI.Analysis.VlasovMaxwell.Model:46.text:
def BoundedSmooth (F : Vec → Vec) : Prop :=
  ContDiff ℝ ∞ F ∧ ∀ n : ℕ, ∃ C : ℝ, ∀ x : Vec,
    ‖iteratedFDeriv ℝ n F x‖ ≤ C

OAI.Analysis.VlasovMaxwell.Model:85.text:
